import java.util.*;

class Solution {
    public String frequencySort(String s) {
        int[] cnt = new int[128];
        for (int i = 0; i < s.length(); i++) cnt[s.charAt(i)]++;
        List<Character> chars = new ArrayList<>();
        for (char c = 0; c < 128; c++) if (cnt[c] > 0) chars.add(c);
        // more frequent first; on a tie, smaller character code first
        Collections.sort(chars, (a, b) -> cnt[a] != cnt[b] ? Integer.compare(cnt[b], cnt[a]) : Character.compare(a, b));
        StringBuilder sb = new StringBuilder(s.length());
        for (char c : chars) for (int k = 0; k < cnt[c]; k++) sb.append(c);
        return sb.toString();
    }
}

