function frequencySort(s) {
  const m = {}; for (const c of s) m[c] = (m[c] || 0) + 1;
  return Object.keys(m).sort((a, b) => (m[b] - m[a]) || (a < b ? -1 : 1)).map(c => c.repeat(m[c])).join("");
}
